from collections.abc import Mapping
import logging

logger = logging.getLogger(__name__)

ARG_LIST_KEY = 'argList'


def get_parsed_context(args: list[str] | None) -> Mapping:
    logger.debug("starting")
    if not args:
        logger.debug(
