            "argskwargs parser you're looking for something like:\n"
            "pypyr pipelinename arg1 arg2 k1=v1 k2=\"v 2\""
        )
        return {ARG_LIST_KEY: []}
    arg_list = []
    out: dict[str, str | list] = {}
    for a in args:
        key, sep, value = a.partition('=')
        if sep:
            out[key] = value
        else:
            arg_list.append(a)

    out[ARG_LIST_KEY] = arg_list

    return out

